func (s MapHeavy) JSONSize() int {
	size := 15
	size += len(s.Labels) * 4
	for k, v := range s.Labels {
		size += len(k) * 2
		size += 2
		size += len(v) * 2
	}
	return size
}

func (s MapHeavy) AppendJSON(dst []byte) ([]byte, error) {
	var err error
	_ = err
	dst = append(dst, "{\"labels\":"...)
	if s.Labels == nil {
		dst = append(dst, "null"...)
	} else {
		dst = append(dst, '{')
		firstLabels := true
		for k, v := range s.Labels {
			if firstLabels {
				firstLabels = false
				dst = append(dst, '"')
			} else {
				dst = append(dst, ",\""...)
			}
			dst = encode.AppendStringNoHTML(dst, k)
			dst = append(dst, ":\""...)
			dst = encode.AppendStringNoHTML(dst, v)
		}
		dst = append(dst, '}')
	}
	return append(dst, '}'), nil
}
